namespace RunnersZ.Logic { public static class AnswerNormalizer { public static string Normalize(string value){if(value==null)return "";var s=value.Trim().ToUpperInvariant().Replace("Ñ","N");var d=s.Normalize(System.Text.NormalizationForm.FormD);var r=new System.Text.StringBuilder();foreach(var c in d)if(System.Globalization.CharUnicodeInfo.GetUnicodeCategory(c)!=System.Globalization.UnicodeCategory.NonSpacingMark)r.Append(char.IsLetterOrDigit(c)||char.IsWhiteSpace(c)?c:' ');return string.Join(" ",r.ToString().Split((char[])null,System.StringSplitOptions.RemoveEmptyEntries));}}}